/** Mock mode: serve the real sample responses from ../samples (generated by the backend). Filters do not change mock data. */
import type { Query } from './client';

const files = import.meta.glob('../../../samples/*.json');

export function sampleFor(path: string, q: Query = {}): string {
  const metric = String(q.metric ?? '');
  switch (path) {
    case '/api/health': return 'health';
    case '/api/filters': return 'filters';
    case '/api/sources': return 'sources';
    case '/api/geo/states': return 'geo_states';
    case '/api/map': return metric === 'growth_pct' ? 'map_growth_pct' : 'map_total_visits';
    case '/api/overview/kpis': return 'overview_kpis';
    case '/api/overview/trend': return 'overview_trend';
    case '/api/rankings': return 'rankings_top10_foreign';
    case '/api/rankings/race': return 'rankings_race';
    case '/api/compare': return 'compare_kl_ga_rj';
    case '/api/scatter': return 'scatter';
    case '/api/states/{code}': return String(q.code).toUpperCase() === 'LA' ? 'state_detail_la_2018_no_data' : 'state_detail_ga';
    case '/api/seasonality/heatmap': return 'seasonality_heatmap';
    case '/api/seasonality/by-type': return 'seasonality_by_type';
    case '/api/festivals': return 'festivals_october';
    case '/api/economy': return 'economy';
    case '/api/infrastructure/demand-capacity': return 'infrastructure_demand_capacity';
    case '/api/infrastructure/occupancy-trend': return 'infrastructure_occupancy_trend';
    case '/api/covid/recovery': return 'covid_recovery';
    case '/api/forecast': return q.state ? 'forecast_kerala_revenue' : 'forecast_national';
    case '/api/anomalies': return 'anomalies';
    case '/api/insights': return q.state ? 'insights_state_kl' : 'insights_national';
    case '/api/ask': return 'ask_top5_foreign';
    default: throw new Error(`No mock sample for ${path}`);
  }
}

export async function mockGet(path: string, q: Query = {}): Promise<unknown> {
  const name = sampleFor(path, q);
  const loader = files[`../../../samples/${name}.json`];
  if (!loader) throw new Error(`Sample ${name}.json not found`);
  await new Promise((r) => setTimeout(r, 120)); // feel like a network call
  const mod = (await loader()) as { default: unknown };
  return mod.default;
}
